import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;

import 'package:flutter_test/flutter_test.dart';
import 'package:run_recorder/run_recorder.dart';

// Golden vectors generated by scripts/gps_distance/reference.py.
// `flutter test` runs with the package root as cwd, so the repo-root fixture
// is two levels up.
Map<String, dynamic> _loadVectors() {
  final file = File('../../fixtures/gps_distance_vectors.json');
  return jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
}

double? _num(Map<String, dynamic> m, String key) =>
    (m[key] as num?)?.toDouble();

GpsEvent _event(Map<String, dynamic> ev) => switch (ev['type']) {
  'fix' => GpsFixEvent(
    t: _num(ev, 't')!,
    lat: _num(ev, 'lat')!,
    lng: _num(ev, 'lng')!,
    accuracyM: _num(ev, 'acc'),
    speedMps: _num(ev, 'speed'),
    speedAccuracyMps: _num(ev, 'speedAcc'),
    bearingDeg: _num(ev, 'bearing'),
  ),
  'steps' => GpsStepsEvent(
    t: _num(ev, 't')!,
    count: (ev['count'] as num).toInt(),
  ),
  'finish' => GpsFinishEvent(t: _num(ev, 't')!),
  _ => throw StateError('unknown event type ${ev['type']}'),
};

void _apply(GpsDistanceEstimator e, GpsEvent ev) {
  switch (ev) {
    case GpsFixEvent():
      e.addFix(
        t: ev.t,
        lat: ev.lat,
        lng: ev.lng,
        accuracyM: ev.accuracyM,
        speedMps: ev.speedMps,
        speedAccuracyMps: ev.speedAccuracyMps,
        bearingDeg: ev.bearingDeg,
      );
    case GpsStepsEvent():
      e.addSteps(ev.t, ev.count);
    case GpsFinishEvent():
      e.finish(ev.t);
  }
}

void main() {
  final vectors = _loadVectors();
  final tolerance = (vectors['tolerance_m'] as num).toDouble();
  final posTolerance = (vectors['position_tolerance_deg'] as num).toDouble();
  final scenarios = (vectors['scenarios'] as List).cast<Map<String, dynamic>>();

  test('fixture is spec v1.7 and carries every scenario', () {
    expect(vectors['spec'], 'gps-distance-estimator v1.7');
    expect(GpsDistanceEstimator.specVersion, '1.7');
    expect(scenarios.length, greaterThanOrEqualTo(53));
  });

  test('constants match the fixture', () {
    final c = (vectors['constants'] as Map).cast<String, num>();
    expect(c['EARTH_RADIUS_M'], GpsDistanceEstimator.earthRadiusM);
    expect(c['Q_ACCEL'], GpsDistanceEstimator.qAccel);
    expect(c['MIN_POS_SIGMA_M'], GpsDistanceEstimator.minPosSigmaM);
    expect(c['MAX_POS_SIGMA_M'], GpsDistanceEstimator.maxPosSigmaM);
    expect(c['MAX_OPEN_GAPS'], GpsDistanceEstimator.maxOpenGaps);
    expect(c['INIT_VEL_VAR'], GpsDistanceEstimator.initVelVar);
    expect(c['MIN_SPEED_SIGMA_MPS'], GpsDistanceEstimator.minSpeedSigmaMps);
    expect(
      c['DEFAULT_SPEED_SIGMA_MPS'],
      GpsDistanceEstimator.defaultSpeedSigmaMps,
    );
    expect(c['MAX_SPEED_SIGMA_MPS'], GpsDistanceEstimator.maxSpeedSigmaMps);
    expect(c['STATIONARY_SPEED_MPS'], GpsDistanceEstimator.stationarySpeedMps);
    expect(
      c['POS_ONLY_STATIONARY_SPEED_MPS'],
      GpsDistanceEstimator.posOnlyStationarySpeedMps,
    );
    expect(c['GAP_S'], GpsDistanceEstimator.gapS);
    expect(c['FRESH_FIX_S'], GpsDistanceEstimator.freshFixS);
    expect(c['STRIDE_WINDOW_STEPS'], GpsDistanceEstimator.strideWindowSteps);
    expect(c['MIN_STRIDE_M'], GpsDistanceEstimator.minStrideM);
    expect(c['MAX_STRIDE_M'], GpsDistanceEstimator.maxStrideM);
    expect(c['STRIDE_EMA_ALPHA'], GpsDistanceEstimator.strideEmaAlpha);
    expect(
      c['STRIDE_MAX_SPEED_SIGMA_MPS'],
      GpsDistanceEstimator.strideMaxSpeedSigmaMps,
    );
    expect(
      c['STRIDE_MAX_POS_SIGMA_M'],
      GpsDistanceEstimator.strideMaxPosSigmaM,
    );
    expect(c['CHECK_MAX_POS_SIGMA_M'], GpsDistanceEstimator.checkMaxPosSigmaM);
    expect(c['GATE_CHI2'], GpsDistanceEstimator.gateChi2);
    expect(c['GATE_MAX_REJECTS'], GpsDistanceEstimator.gateMaxRejects);
    expect(c['R_SCALE_ALPHA'], GpsDistanceEstimator.rScaleAlpha);
    expect(c['R_SCALE_MIN'], GpsDistanceEstimator.rScaleMin);
    expect(c['R_SCALE_MAX'], GpsDistanceEstimator.rScaleMax);
    expect(c['XCHECK_TAU_S'], GpsDistanceEstimator.xcheckTauS);
    expect(c['XCHECK_MIN_S'], GpsDistanceEstimator.xcheckMinS);
    expect(c['XCHECK_ENTER_ABS_MPS'], GpsDistanceEstimator.xcheckEnterAbsMps);
    expect(c['XCHECK_ENTER_REL'], GpsDistanceEstimator.xcheckEnterRel);
    expect(c['XCHECK_EXIT_ABS_MPS'], GpsDistanceEstimator.xcheckExitAbsMps);
    expect(c['XCHECK_EXIT_REL'], GpsDistanceEstimator.xcheckExitRel);
    expect(c['XCHECK_PERSIST_S'], GpsDistanceEstimator.xcheckPersistS);
    expect(c['XCHECK_MAX_SPAN_S'], GpsDistanceEstimator.xcheckMaxSpanS);
    expect(c['DEBIAS_FULL_MPS'], GpsDistanceEstimator.debiasFullMps);
    expect(c['DEBIAS_ZERO_MPS'], GpsDistanceEstimator.debiasZeroMps);
    expect(c['DSCALE_TAU_S'], GpsDistanceEstimator.dscaleTauS);
    expect(c['DSCALE_MIN_S'], GpsDistanceEstimator.dscaleMinS);
    expect(c['DSCALE_MIN'], GpsDistanceEstimator.dscaleMin);
    expect(c['DSCALE_MAX'], GpsDistanceEstimator.dscaleMax);
    expect(c['DSCALE_MIN_SPEED_MPS'], GpsDistanceEstimator.dscaleMinSpeedMps);
    expect(c['DSCALE_MAX_TURN_DEG'], GpsDistanceEstimator.dscaleMaxTurnDeg);
    expect(c['ZUPT_NO_STEP_S'], GpsDistanceEstimator.zuptNoStepS);
    expect(c['ZUPT_VEL_SIGMA_MPS'], GpsDistanceEstimator.zuptVelSigmaMps);
    expect(
      c['ZUPT_DOPPLER_OVERRIDE_MPS'],
      GpsDistanceEstimator.zuptDopplerOverrideMps,
    );
    expect(c['ZUPT_RELEASE_M'], GpsDistanceEstimator.zuptReleaseM);
    expect(
      c['ZUPT_BATCH_MIN_CADENCE_SPS'],
      GpsDistanceEstimator.zuptBatchMinCadenceSps,
    );
    expect(c['ZUPT_BATCH_MARGIN'], GpsDistanceEstimator.zuptBatchMargin);
    expect(c['ZUPT_MAX_NO_STEP_S'], GpsDistanceEstimator.zuptMaxNoStepS);
    expect(c['STOP_HALF_WINDOW_S'], GpsDistanceEstimator.stopHalfWindowS);
    expect(c['STOP_MIN_HALF_FIXES'], GpsDistanceEstimator.stopMinHalfFixes);
    expect(c['STOP_SPEED_MPS'], GpsDistanceEstimator.stopSpeedMps);
    expect(c['STOP_RADIUS_M'], GpsDistanceEstimator.stopRadiusM);
    // Every fixture constant is pinned above; a new one fails here until it is.
    expect(c.length, 52);
  });

  group('golden vectors', () {
    for (final s in scenarios) {
      test(s['name'] as String, () {
        final e = GpsDistanceEstimator(
          maxSpeedMps: _num(s, 'maxSpeedMps')!,
          expectedIntervalS: _num(s, 'expectedIntervalS')!,
          initialStrideM: _num(s, 'initialStrideM'),
          learnStride: s['learnStride'] as bool,
        );
        final events = (s['events'] as List)
            .cast<Map<String, dynamic>>()
            .map(_event)
            .toList();
        final expected = s['expected'] as Map<String, dynamic>;
        final after = (expected['distanceAfterEachEventM'] as List)
            .map((v) => (v as num).toDouble())
            .toList();
        expect(after, hasLength(events.length));
        for (var i = 0; i < events.length; i++) {
          _apply(e, events[i]);
          expect(
            e.distanceM,
            closeTo(after[i], tolerance),
            reason: 'distance after event $i (${events[i].runtimeType})',
          );
        }
        expect(
          e.gpsDistanceM,
          closeTo(_num(expected, 'gpsDistanceM')!, tolerance),
        );
        expect(
          e.stepDistanceM,
          closeTo(_num(expected, 'stepDistanceM')!, tolerance),
        );
        expect(
          e.stepOverChordM,
          closeTo(_num(expected, 'stepOverChordM')!, tolerance),
        );
        final stride = _num(expected, 'strideM');
        if (stride == null) {
          expect(e.strideM, isNull);
        } else {
          expect(e.strideM, isNotNull);
          expect(e.strideM!, closeTo(stride, tolerance));
        }
        expect(e.rejectedFixes, expected['rejectedFixes']);
        expect(e.zuptFixes, expected['zuptFixes']);
        expect(e.dopplerTrusted, expected['dopplerTrusted']);
        expect(e.rScale, closeTo(_num(expected, 'rScale')!, 1e-6));
        expect(e.dopplerScale, closeTo(_num(expected, 'dopplerScale')!, 1e-6));
      });
    }
  });

  group('smoothed golden vectors', () {
    for (final s in scenarios) {
      test(s['name'] as String, () {
        final events = (s['events'] as List)
            .cast<Map<String, dynamic>>()
            .map(_event)
            .toList();
        final want = s['smoothed'] as Map<String, dynamic>;
        final got = smoothDistance(
          events,
          maxSpeedMps: _num(s, 'maxSpeedMps')!,
          expectedIntervalS: _num(s, 'expectedIntervalS')!,
          initialStrideM: _num(s, 'initialStrideM'),
          learnStride: s['learnStride'] as bool,
        );
        final after = (want['distanceAfterEachEventM'] as List)
            .map((v) => (v as num).toDouble())
            .toList();
        expect(got.cumulativeM, hasLength(events.length));
        for (var i = 0; i < events.length; i++) {
          expect(
            got.cumulativeM[i],
            closeTo(after[i], tolerance),
            reason: 'smoothed distance after event $i',
          );
        }
        expect(got.distanceM, closeTo(_num(want, 'distanceM')!, tolerance));
        expect(
          got.gpsDistanceM,
          closeTo(_num(want, 'gpsDistanceM')!, tolerance),
        );
        expect(
          got.stepDistanceM,
          closeTo(_num(want, 'stepDistanceM')!, tolerance),
        );
        expect(
          got.stepOverChordM,
          closeTo(_num(want, 'stepOverChordM')!, tolerance),
        );
        expect(got.stoppedFixes, want['stoppedFixes']);
        final positions = want['positions'] as List;
        expect(got.positions, hasLength(positions.length));
        for (var i = 0; i < positions.length; i++) {
          final w = positions[i] as List?;
          final p = got.positions[i];
          if (w == null) {
            expect(p, isNull, reason: 'position $i');
            continue;
          }
          expect(p, isNotNull, reason: 'position $i');
          expect(
            p!.lat,
            closeTo((w[0] as num).toDouble(), posTolerance),
            reason: 'lat $i',
          );
          expect(
            p.lng,
            closeTo((w[1] as num).toDouble(), posTolerance),
            reason: 'lng $i',
          );
        }
      });
    }
  });

  group('non-finite input', () {
    GpsDistanceEstimator running() {
      final e = GpsDistanceEstimator();
      for (var i = 0; i < 5; i++) {
        e.addFix(
          t: i.toDouble(),
          lat: 40 + i * 0.000025,
          lng: -75,
          accuracyM: 4,
          speedMps: 2.7,
          speedAccuracyMps: 0.4,
          bearingDeg: 0,
        );
      }
      return e;
    }

    test('a NaN or infinite time, latitude or longitude credits nothing', () {
      final e = running();
      final before = e.distanceM;
      expect(e.addFix(t: double.nan, lat: 40.0002, lng: -75), 0);
      expect(e.addFix(t: double.infinity, lat: 40.0002, lng: -75), 0);
      expect(e.addFix(t: 5, lat: double.nan, lng: -75), 0);
      expect(e.addFix(t: 5, lat: 40.0002, lng: double.negativeInfinity), 0);
      expect(e.distanceM, before);
      expect(e.distanceM.isFinite, isTrue);
    });

    test(
      'a NaN accuracy, speed or bearing falls back instead of poisoning',
      () {
        final e = running();
        e.addFix(
          t: 5,
          lat: 40.000125,
          lng: -75,
          accuracyM: double.nan,
          speedMps: double.nan,
          speedAccuracyMps: double.nan,
          bearingDeg: double.nan,
        );
        e.addFix(
          t: 6,
          lat: 40.00015,
          lng: -75,
          accuracyM: double.infinity,
          speedMps: 2.7,
          speedAccuracyMps: double.infinity,
          bearingDeg: double.infinity,
        );
        expect(e.distanceM.isFinite, isTrue);
        expect(e.gpsDistanceM, greaterThan(0));
      },
    );

    test('a NaN step time is ignored and finish(NaN) commits nothing', () {
      final e = running();
      e.addSteps(double.nan, 100);
      e.finish(double.nan);
      expect(e.stepDistanceM, 0);
      expect(e.distanceM.isFinite, isTrue);
    });
  });

  group('constructor', () {
    test('a non-finite or sub-second interval hint behaves as 1 s', () {
      // An 11 s interval is a gap at 1 s, credited only by its chord less the
      // 1-sigma uncertainty of both ends: sqrt(9 + 9 + 2 * 9) = 6 m.
      final chord = 0.0003 * math.pi / 180 * GpsDistanceEstimator.earthRadiusM;
      for (final it in [double.nan, double.infinity, 0.5, -3.0]) {
        final e = GpsDistanceEstimator(expectedIntervalS: it);
        e.addFix(t: 0, lat: 40, lng: -75);
        e.addFix(t: 11, lat: 40.0003, lng: -75);
        expect(
          e.gpsDistanceM,
          closeTo(chord - 6, 1e-6),
          reason: 'interval $it',
        );
      }
    });

    test('initial stride is kept only when finite and in range', () {
      expect(GpsDistanceEstimator(initialStrideM: 1.1).strideM, 1.1);
      expect(GpsDistanceEstimator(initialStrideM: 0.3).strideM, isNull);
      expect(GpsDistanceEstimator(initialStrideM: 2.6).strideM, isNull);
      expect(GpsDistanceEstimator(initialStrideM: double.nan).strideM, isNull);
    });
  });

  group('v1.4', () {
    test('a fix stating worse than maxPosSigmaM is ignored outright', () {
      final e = GpsDistanceEstimator();
      expect(e.addFix(t: 0, lat: 40, lng: -75, accuracyM: 51), 0);
      e.addFix(t: 1, lat: 40, lng: -75, accuracyM: 50);
      e.addFix(
        t: 2,
        lat: 40.00003,
        lng: -75,
        accuracyM: 51,
        speedMps: 3,
        speedAccuracyMps: 0.3,
        bearingDeg: 0,
      );
      expect(e.distanceM, 0);
    });

    test('learnStride false never learns a stride, and keeps a seeded one', () {
      for (final seed in [null, 0.95]) {
        final e = GpsDistanceEstimator(
          initialStrideM: seed,
          learnStride: false,
        );
        for (var i = 0; i < 120; i++) {
          e.addFix(
            t: i.toDouble(),
            lat: 40 + i * 0.000025,
            lng: -75,
            accuracyM: 4,
            speedMps: 2.78,
            speedAccuracyMps: 0.3,
            bearingDeg: 0,
          );
          e.addSteps(i + 0.5, (i + 1) * 3);
        }
        expect(e.strideM, seed);
      }
    });
  });

  group('v1.5', () {
    test('the ZUPT window stretches to the step batches walking delivers', () {
      final e = GpsDistanceEstimator();
      e.addSteps(0, 0);
      e.addSteps(1, 2);
      e.addSteps(16, 29);
      expect(e.stepBatchS, 15);
      expect(e.zuptWindowS, 22.5);
      e.addSteps(41, 72);
      expect(e.zuptWindowS, GpsDistanceEstimator.zuptMaxNoStepS);
    });

    test('a stop then a few steps is not a batch, so the window stays put', () {
      final e = GpsDistanceEstimator();
      e.addSteps(0, 0);
      e.addSteps(1, 2);
      e.addSteps(2, 4);
      e.addSteps(62, 8);
      expect(e.stepBatchS, 1);
      expect(e.zuptWindowS, GpsDistanceEstimator.zuptNoStepS);
    });

    test(
      'a fused pocket walk with 15 s step batches is not read as stopped',
      () {
        final e = GpsDistanceEstimator(
          maxSpeedMps: 5,
          initialStrideM: 0.72,
          learnStride: false,
        );
        for (var i = 0; i < 300; i++) {
          e.addFix(
            t: i.toDouble(),
            lat: 40 + i * 1.3 / 111195,
            lng: -75,
            accuracyM: 4,
          );
          if ((i + 1) % 15 == 0) e.addSteps(i + 0.5, ((i + 1) * 1.8).floor());
        }
        expect(e.zuptFixes, lessThanOrEqualTo(9));
        expect(e.distanceM, closeTo(300 * 1.3, 300 * 1.3 * 0.05));
      },
    );
  });

  group('v1.6', () {
    GpsDistanceEstimator eastward() {
      final e = GpsDistanceEstimator(initialStrideM: 0.5, learnStride: false);
      for (var i = 0; i <= 25; i++) {
        e.addFix(
          t: i.toDouble(),
          lat: 40,
          lng: -75 + 4.0 * i / (111195 * math.cos(40 * math.pi / 180)),
          accuracyM: 3,
          speedMps: 4,
          speedAccuracyMps: 0.3,
          bearingDeg: 90,
        );
        e.addSteps(i + 0.5, 4 * i + 2);
      }
      return e;
    }

    test('a late step batch tops a gap up without counting its chord twice',
        () {
      // Steps at 0.5 m credit 2 m/s, so the straight 30 s gap's 116 m chord
      // lower bound wins. The batch after the resuming fix moves 10 m of
      // that credit from the chord to the steps and adds nothing.
      final e = eastward();
      e.addSteps(50, 202);
      e.addFix(
        t: 55,
        lat: 40,
        lng: -75 + 220 / (111195 * math.cos(40 * math.pi / 180)),
        accuracyM: 3,
        speedMps: 4,
        speedAccuracyMps: 0.3,
        bearingDeg: 90,
      );
      final before = e.distanceM;
      final steps = e.stepDistanceM;
      e.addSteps(56.5, 228);
      expect(e.distanceM, closeTo(before, 1e-9));
      expect(e.stepDistanceM - steps, closeTo(10, 1e-9));
    });

    test('a late sample stamped inside a gap shares only its own interval',
        () {
      // 2 steps over (50, 51] at a 0.5 m stride credit 1 m; sharing the rest
      // of the gap, which the fix at 55 closed before the sample arrived, at
      // the sample's rate would credit 5 m.
      final e = eastward();
      e.addSteps(50, 202);
      e.addFix(
        t: 55,
        lat: 40,
        lng: -75 + 110 / (111195 * math.cos(40 * math.pi / 180)),
        accuracyM: 3,
        speedMps: 4,
        speedAccuracyMps: 0.3,
        bearingDeg: 90,
      );
      final before = e.distanceM;
      final steps = e.stepDistanceM;
      e.addSteps(51, 204);
      expect(e.distanceM - before, closeTo(1, 1e-9));
      expect(e.stepDistanceM - steps, closeTo(1, 1e-9));
    });

    test('a fix bridging a short stall teaches no stride from its credit', () {
      // 4 m/s at 4 steps/s is a 1 m stride. The fix at 36 bridges a 7 s stall
      // whose samples emptied the window; feeding its 28 m to the window
      // learns 1.092 m, and letting the sample at 36.5 refill it 0.985 m.
      final e = GpsDistanceEstimator();
      for (var i = 0; i <= 60; i++) {
        if (i < 30 || i >= 36) {
          e.addFix(
            t: i.toDouble(),
            lat: 40,
            lng: -75 + 4.0 * i / (111195 * math.cos(40 * math.pi / 180)),
            accuracyM: 3,
            speedMps: 4,
            speedAccuracyMps: 0.3,
            bearingDeg: 90,
          );
        }
        e.addSteps(i + 0.5, 4 * i + 2);
      }
      expect(e.strideM, closeTo(1.0, 1e-9));
    });

    test('the first step sample of a stretch starts the stride window', () {
      // 4 m/s at 4 steps/s is a 1 m stride. The first sample, at 15.5, only
      // sets the baseline; counting the window's metres from the first fix
      // put 30 s of metres against 15 s of steps and learned 2.0 m, then
      // 1.64 m by 60.5.
      final e = GpsDistanceEstimator();
      for (var i = 0; i <= 60; i++) {
        e.addFix(
          t: i.toDouble(),
          lat: 40,
          lng: -75 + 4.0 * i / (111195 * math.cos(40 * math.pi / 180)),
          accuracyM: 3,
          speedMps: 4,
          speedAccuracyMps: 0.3,
          bearingDeg: 90,
        );
        if (i > 0 && i % 15 == 0) e.addSteps(i + 0.5, 4 * i + 2);
      }
      expect(e.strideM, closeTo(1.0, 1e-6));
    });

    test('a stale first step sample keeps a bridged stall out of the stride window', () {
      // 4 m/s at 4 steps/s is a 1 m stride. The first sample, at 14.5, lands
      // inside a 7 s stall the fix at 18 bridges, so it is stale as well as
      // the baseline; the bridging fix must empty the window rather than feed
      // it 28 m, which learned 1.171 m.
      final e = GpsDistanceEstimator();
      for (var i = 0; i <= 60; i++) {
        if (i < 11 || i > 17) {
          e.addFix(
            t: i.toDouble(),
            lat: 40,
            lng: -75 + 4.0 * i / (111195 * math.cos(40 * math.pi / 180)),
            accuracyM: 3,
            speedMps: 4,
            speedAccuracyMps: 0.3,
            bearingDeg: 90,
          );
        }
        if (i % 15 == 14) e.addSteps(i + 0.5, 4 * i + 2);
      }
      expect(e.strideM, closeTo(1.0, 1e-6));
    });

    test('the first fix of a stretch starts the stride window', () {
      // The first sample, at 0.5, and the second, at 15.5, come before the
      // first fix at 20; the first fix starts the window, so the sample at
      // 30.5, whose interval began before it, empties the window rather than
      // pairing 15 s of steps with 10 s of metres, which learned 0.787 m.
      final e = GpsDistanceEstimator();
      for (var i = 0; i <= 60; i++) {
        if (i >= 20) {
          e.addFix(
            t: i.toDouble(),
            lat: 40,
            lng: -75 + 4.0 * i / (111195 * math.cos(40 * math.pi / 180)),
            accuracyM: 3,
            speedMps: 4,
            speedAccuracyMps: 0.3,
            bearingDeg: 90,
          );
        }
        if (i % 15 == 0) e.addSteps(i + 0.5, 4 * i + 2);
      }
      expect(e.strideM, closeTo(1.0, 1e-6));
    });

    test('a stretch credits no steps taken before its first fix', () {
      final e = GpsDistanceEstimator(initialStrideM: 1.0, learnStride: false);
      for (var i = 0; i < 30; i++) {
        e.addSteps(i + 0.5, 4 * i);
      }
      e.addFix(t: 30, lat: 40, lng: -75, accuracyM: 3);
      e.finish(31);
      expect(e.distanceM, 0);
    });
  });

  group('v1.7', () {
    final eastMPerDeg = 111195 * math.cos(40 * math.pi / 180);

    void fix(GpsDistanceEstimator e, double t, double eastM) => e.addFix(
          t: t,
          lat: 40,
          lng: -75 + eastM / eastMPerDeg,
          accuracyM: 3,
          speedMps: 4,
          speedAccuracyMps: 0.3,
          bearingDeg: 90,
        );

    test('a step baseline delivered after a later fix keeps its steps out of the stride window', () {
      // The baseline, stamped 15.5, arrives after the fix at 18, so the
      // window's metres start at 18; the sample at 30.5, whose steps start at
      // 15.5, must empty the window rather than pair 15 s of steps with 12 s
      // of metres, which learned 0.8 m.
      final e = GpsDistanceEstimator();
      for (var i = 0; i <= 60; i++) {
        fix(e, i.toDouble(), 4.0 * i);
        if (i == 18) e.addSteps(15.5, 62);
        if (i > 15 && i % 15 == 0) e.addSteps(i + 0.5, 4 * i + 2);
      }
      expect(e.strideM, closeTo(1.0, 1e-6));
    });

    test('stepOverChordM counts only the steps a gap credited beyond its chord', () {
      // A seeded 1 m stride, 4 m/s and 4 steps/s, then a 26 s fix gap whose
      // 104 m of steps the resuming fix puts beside no chord (the runner
      // looped back), a 55.39 m one, and one longer than the steps.
      for (final (eastM, want) in [(24.0, 104.0), (80.0, 48.612667), (160.0, 0.0)]) {
        final e = GpsDistanceEstimator(initialStrideM: 1.0, learnStride: false);
        for (var i = 0; i <= 30; i++) {
          if (i <= 5) fix(e, i.toDouble(), 4.0 * i);
          e.addSteps(i + 0.5, 4 * i + 2);
        }
        fix(e, 31, eastM);
        e.addSteps(31.5, 126);
        expect(e.stepDistanceM, closeTo(104, 1e-9));
        expect(e.stepOverChordM, closeTo(want, 1e-6), reason: 'resume $eastM m');
      }
    });
  });
}
